def basis(x, k, kind, e):
    from scipy.special import erf
    z = k * x
    if kind == 'tanh':
        f = np.tanh(z)
    if kind == 'rat':
        f = z / (1 + z * z)
    if kind == 'root':
        f = z / np.sqrt(1 + z * z)
    if kind == 'atan':
        f = np.arctan(z)
    if kind == 'erf':
        from scipy.special import erf
        f = erf(z)
    if kind == 'poly':
        f = x ** 3
    terms = [np.ones(len(x)), x, x * x, f]
    if e == 'f2':
        terms += [f * f]
    if e == 'rat2':
        terms += [x * x / (1 + z * z)]
    return np.column_stack(terms)

def solve(A, y):
    c = np.linalg.lstsq(A, y, rcond=None)[0]
    return A @ c - y
